const existingRequestedScientificNames = new Set(EXOTIC_ANIMALS_DATA.map(species => String(species.scientificName || '').trim().toLocaleLowerCase('en-US')));
const existingRequestedNames = new Set(EXOTIC_ANIMALS_DATA.map(species => String(species.name || '').trim().toLocaleLowerCase('tr-TR')));
EXOTIC_ANIMALS_DATA = [
  ...EXOTIC_ANIMALS_DATA,
  ...REQUESTED_SPECIES_DATA.filter(species => !existingRequestedIds.has(species.id) && !existingRequestedScientificNames.has(species.scientificName.toLocaleLowerCase('en-US')) && !existingRequestedNames.has(species.name.toLocaleLowerCase('tr-TR')))
];
